style.css:
@-moz-document domain("google.com") {
/* Hide the default Google logo */
    img[alt="Google"], .lnXdpd {
        display: none !important;
    }
    
    /* Create an NYC-style custom text logo */
    body::before {
        content: "GOOGLE";
        font-family: 'Arial', sans-serif; /* Simple NYC-style font without bold */
        font-size: 60px;
        color: #fff;
        text-transform: uppercase;
        text-align: center;
        display: block;
        margin: 20px auto;
        width: 100%;
        text-shadow: 4px 4px 0px #ff0000, 8px 8px 0px #0000ff; /* NYC graffiti-style shadow */
        font-weight: normal; /* Ensure no bold effect */
    }
    
    /* Set NYC Night 4K background */
    body {
        background: url('https://wallpapercave.com/wp/wp6754236.jpg') no-repeat center center fixed;
        background-size: cover;
    }
}
